/* ============================================
   GreenBean Coffee — Global Styles
   ============================================ */

:root {
  --primary-green: #00824A;
  --dark-forest: #32462F;
  --warm-cream: #F3CEA1;
  --white: #FFFFFF;
  --off-white: #F9F9F7;
  --light-gray: #F3F3F0;
  --mid-gray: #9CA3AF;
  --dark-gray: #4B5563;
  --text-primary: #1F2937;
  --text-secondary: #6B7280;
  --border-color: #E5E7EB;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --transition: 0.25s ease;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--text-primary);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { text-decoration: none; color: inherit; }

ul { list-style: none; }

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4 {
  font-family: 'DM Sans', 'Inter', sans-serif;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p { color: var(--text-secondary); }

/* ============================================
   Buttons
   ============================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-xl);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--primary-green);
  color: var(--white);
  border-color: var(--primary-green);
}

.btn-primary:hover {
  background: var(--dark-forest);
  border-color: var(--dark-forest);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--primary-green);
  border-color: var(--primary-green);
}

.btn-outline:hover {
  background: var(--primary-green);
  color: var(--white);
}

.btn-white {
  background: var(--white);
  color: var(--primary-green);
  border-color: var(--white);
}

.btn-white:hover {
  background: var(--light-gray);
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* ============================================
   Header / Navigation
   ============================================ */

.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'DM Sans', sans-serif;
  font-weight: 800;
  font-size: 1.35rem;
  color: var(--primary-green);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary-green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1rem;
}

.nav-main {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-main a {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-primary);
  position: relative;
  padding: 4px 0;
}

.nav-main a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary-green);
  transition: width var(--transition);
}

.nav-main a:hover::after,
.nav-main a.active::after {
  width: 100%;
}

.nav-main a:hover,
.nav-main a.active {
  color: var(--primary-green);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-actions a {
  font-weight: 600;
  font-size: 0.9rem;
}

.nav-actions .btn-sm {
  padding: 8px 18px;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--text-primary);
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--dark-forest) 0%, var(--primary-green) 100%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 70%;
  height: 200%;
  background: radial-gradient(circle, rgba(243,206,161,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
  padding: 80px 0;
}

.hero h1 {
  color: var(--white);
  margin-bottom: 20px;
}

.hero p {
  color: rgba(255,255,255,0.85);
  font-size: 1.15rem;
  margin-bottom: 32px;
  max-width: 480px;
}

.hero-visual {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 45%;
  max-width: 520px;
  aspect-ratio: 1;
  background: radial-gradient(circle, var(--warm-cream) 0%, transparent 60%);
  border-radius: 50%;
  opacity: 0.25;
}

/* ============================================
   Promo / Feature Cards
   ============================================ */

.promo-section {
  padding: 80px 0;
}

.promo-section.alt-bg {
  background: var(--off-white);
}

.promo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.promo-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  border: 1px solid var(--border-color);
}

.promo-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.promo-card-img {
  width: 100%;
  height: 220px;
  background: linear-gradient(135deg, var(--light-gray), var(--warm-cream));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--primary-green);
}

.promo-card-body {
  padding: 28px;
}

.promo-card-body h3 {
  margin-bottom: 10px;
  color: var(--text-primary);
}

.promo-card-body p {
  margin-bottom: 20px;
  font-size: 0.95rem;
}

/* Split promo (image + text side by side) */
.promo-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.promo-split-img {
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 360px;
  background: linear-gradient(135deg, var(--warm-cream), var(--light-gray));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  color: var(--primary-green);
}

.promo-split-content h2 {
  margin-bottom: 16px;
}

.promo-split-content p {
  margin-bottom: 28px;
  font-size: 1.05rem;
  max-width: 440px;
}

/* ============================================
   Seasonal Highlights
   ============================================ */

.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.seasonal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 40px;
  background: linear-gradient(135deg, var(--dark-forest), var(--primary-green));
}

.seasonal-card:nth-child(2) {
  background: linear-gradient(135deg, #6B4F3A, #A67B5B);
}

.seasonal-card h3 {
  color: var(--white);
  margin-bottom: 10px;
  font-size: 1.75rem;
}

.seasonal-card p {
  color: rgba(255,255,255,0.9);
  margin-bottom: 24px;
  max-width: 360px;
}

.seasonal-card .btn-white {
  align-self: flex-start;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  background: var(--dark-forest);
  color: var(--white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-size: 1rem;
  margin-bottom: 16px;
  color: var(--warm-cream);
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer-col ul li a:hover {
  color: var(--white);
}

.footer-accordion-toggle {
  display: none;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition);
}

.footer-social a:hover {
  background: var(--primary-green);
}

.footer-copy {
  color: rgba(255,255,255,0.5);
  font-size: 0.85rem;
}

/* ============================================
   Cookie Banner
   ============================================ */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--border-color);
  padding: 20px 24px;
  z-index: 200;
  box-shadow: var(--shadow-lg);
  transform: translateY(0);
  transition: transform 0.4s ease;
}

.cookie-banner.hidden {
  transform: translateY(120%);
}

.cookie-inner {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-inner p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  flex: 1;
  min-width: 280px;
}

.cookie-inner p strong {
  color: var(--text-primary);
  display: block;
  margin-bottom: 4px;
  font-size: 1rem;
}

.cookie-actions {
  display: flex;
  gap: 12px;
}

/* ============================================
   Menu Page
   ============================================ */

.breadcrumb {
  padding: 20px 0;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.breadcrumb a:hover {
  color: var(--primary-green);
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 48px;
  padding: 24px 0 64px;
}

.menu-sidebar {
  position: sticky;
  top: 96px;
  height: fit-content;
}

.menu-sidebar h3 {
  font-size: 1.125rem;
  margin-bottom: 20px;
  color: var(--text-primary);
}

.sidebar-group {
  margin-bottom: 24px;
}

.sidebar-group-title {
  font-weight: 700;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--mid-gray);
  margin-bottom: 10px;
}

.sidebar-group ul li {
  margin-bottom: 6px;
}

.sidebar-group ul li a {
  display: block;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: all var(--transition);
}

.sidebar-group ul li a:hover,
.sidebar-group ul li a.active {
  background: rgba(0,130,74,0.08);
  color: var(--primary-green);
}

.menu-section {
  margin-bottom: 48px;
}

.menu-section h2 {
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--border-color);
}

.menu-category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.menu-item {
  background: var(--white);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
  transition: all var(--transition);
}

.menu-item:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.menu-item-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 12px;
  background: var(--light-gray);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--primary-green);
}

.menu-item h4 {
  font-size: 0.95rem;
  margin-bottom: 4px;
}

.menu-item p {
  font-size: 0.8rem;
}

/* ============================================
   Rewards Page
   ============================================ */

.rewards-hero {
  background: linear-gradient(135deg, var(--dark-forest), var(--primary-green));
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}

.rewards-hero h1 {
  margin-bottom: 12px;
}

.rewards-hero p {
  color: rgba(255,255,255,0.85);
  font-size: 1.15rem;
  max-width: 560px;
  margin: 0 auto 32px;
}

.how-it-works {
  padding: 64px 0;
  background: var(--off-white);
}

.how-it-works h2 {
  text-align: center;
  margin-bottom: 48px;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.step-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
}

.step-number {
  width: 48px;
  height: 48px;
  background: var(--primary-green);
  color: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  margin: 0 auto 20px;
}

.step-card h3 {
  margin-bottom: 10px;
}

.tiers-section {
  padding: 64px 0;
}

.tiers-section h2 {
  text-align: center;
  margin-bottom: 48px;
}

.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.tier-card {
  background: var(--white);
  border: 2px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  text-align: center;
  transition: all var(--transition);
}

.tier-card.featured {
  border-color: var(--primary-green);
  box-shadow: var(--shadow-md);
}

.tier-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.tier-badge {
  display: inline-block;
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}

.tier-badge.green { background: #D1FAE5; color: #065F46; }
.tier-badge.gold { background: #FEF3C7; color: #92400E; }
.tier-badge.reserve { background: #E0E7FF; color: #3730A3; }

.tier-card h3 {
  margin-bottom: 8px;
}

.tier-stars {
  font-size: 0.95rem;
  color: var(--primary-green);
  font-weight: 600;
  margin-bottom: 20px;
}

.tier-benefits {
  text-align: left;
}

.tier-benefits li {
  padding: 6px 0;
  font-size: 0.9rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
}

.tier-benefits li:last-child { border-bottom: none; }

/* Redemption Tabs */
.redemption-section {
  padding: 64px 0;
  background: var(--off-white);
}

.redemption-section h2 {
  text-align: center;
  margin-bottom: 12px;
}

.redemption-subtitle {
  text-align: center;
  margin-bottom: 40px;
}

.redemption-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.redemption-tab {
  padding: 12px 20px;
  border-radius: var(--radius-xl);
  border: 2px solid var(--border-color);
  background: var(--white);
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all var(--transition);
  color: var(--text-secondary);
}

.redemption-tab:hover {
  border-color: var(--primary-green);
  color: var(--primary-green);
}

.redemption-tab.active {
  background: var(--primary-green);
  border-color: var(--primary-green);
  color: var(--white);
}

.redemption-panel {
  display: none;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
}

.redemption-panel.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-panel .stars-display {
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary-green);
  margin-bottom: 8px;
}

.redemption-panel .reward-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.redemption-panel .reward-value {
  color: var(--primary-green);
  font-weight: 600;
}

/* Partnerships */
.partnerships {
  padding: 64px 0;
  text-align: center;
}

.partnerships h2 {
  margin-bottom: 40px;
}

.partner-grid {
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
}

.partner-card {
  background: var(--white);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 360px;
  text-align: left;
  transition: all var(--transition);
}

.partner-card:hover {
  box-shadow: var(--shadow-md);
}

.partner-card h4 {
  margin-bottom: 8px;
}

/* App Download */
.app-download {
  padding: 64px 0;
  background: linear-gradient(135deg, var(--dark-forest), var(--primary-green));
  color: var(--white);
  text-align: center;
}

.app-download h2 {
  margin-bottom: 12px;
}

.app-download p {
  color: rgba(255,255,255,0.85);
  margin-bottom: 28px;
}

.app-buttons {
  display: flex;
  justify-content: center;
  gap: 16px;
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 24px;
  background: var(--white);
  color: var(--text-primary);
  border-radius: var(--radius-md);
  font-weight: 600;
  transition: all var(--transition);
}

.app-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

/* ============================================
   Gift Cards Page
   ============================================ */

.gift-hero {
  background: linear-gradient(135deg, #6B4F3A, #A67B5B);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}

.gift-hero h1 {
  margin-bottom: 12px;
}

.gift-hero p {
  color: rgba(255,255,255,0.9);
  max-width: 520px;
  margin: 0 auto 32px;
}

/* Carousel */
.carousel-section {
  padding: 48px 0;
}

.carousel-section h2 {
  margin-bottom: 24px;
}

.carousel-wrap {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 8px 4px 24px;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 240px;
  scroll-snap-align: start;
  background: var(--white);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition);
}

.carousel-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.carousel-card-img {
  height: 150px;
  background: linear-gradient(135deg, var(--warm-cream), #E8D5C4);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.carousel-card-body {
  padding: 16px;
}

.carousel-card-body h4 {
  font-size: 0.95rem;
  margin-bottom: 4px;
}

.carousel-card-body p {
  font-size: 0.8rem;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1.25rem;
  color: var(--text-primary);
